data: {"index":1,"delta":{"text":" generates the target machine code). \n\nHere is how a compiler works, stage by stage.\n\n---\n\n### 1","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":". Lexical Analysis (Scanning)\nThe journey begins with the **Lexical Analyzer**, or **lexer**. The lex","type":"text"},"event_type":"step.delta"}

